pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(address nonOwner, uint256 amount, bytes memory data) public {
        vm.assume(nonOwner != address(this) && nonOwner != address(c) && nonOwner != address(0));
        Receiver receiver = new Receiver();
        vm.deal(nonOwner, amount);
        vm.prank(nonOwner);
        bool ok;
        try c.sendMoney(address(receiver), amount, data) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(!ok);
    }
}

contract Receiver {
    fallback() external payable { }
}
